"use client";

import { useState } from "react";
import { Search, Bell, User, Loader2 } from "lucide-react";

export default function Header() {
  const [searchQuery, setSearchQuery] = useState("");
  const [isSearching, setIsSearching] = useState(false);
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const [showDropdown, setShowDropdown] = useState(false);

  // Mock search function to mimic GET /api/search
  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setSearchQuery(value);
    
    if (value.trim().length > 0) {
      setShowDropdown(true);
      setIsSearching(true);
      // Simulate API call
      setTimeout(() => {
        setSearchResults([
          { id: 1, title: "Đơn xin nghỉ phép - Nguyễn Văn A", type: "request" },
          { id: 2, title: "Báo cáo doanh thu tháng 9", type: "report" },
        ]);
        setIsSearching(false);
      }, 500);
    } else {
      setShowDropdown(false);
      setSearchResults([]);
    }
  };

  return (
    <header className="h-16 bg-white border-b border-slate-200 px-6 flex items-center justify-between sticky top-0 z-10">
      {/* Left side spacer for balance if needed */}
      <div className="w-1/4"></div>

      {/* Middle: Search Bar (SCRUM-49) */}
      <div className="w-2/4 max-w-xl relative">
        <div className="relative group">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search size={18} className="text-slate-400 group-focus-within:text-indigo-500 transition-colors" />
          </div>
          <input
            type="text"
            className="block w-full pl-10 pr-3 py-2 border border-slate-200 rounded-full leading-5 bg-slate-50 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 focus:bg-white transition-all sm:text-sm"
            placeholder="Tìm kiếm nhân viên, đơn từ, báo cáo..."
            value={searchQuery}
            onChange={handleSearch}
            onFocus={() => searchQuery.trim().length > 0 && setShowDropdown(true)}
            onBlur={() => setTimeout(() => setShowDropdown(false), 200)}
          />
        </div>

        {/* Search Results Dropdown */}
        {showDropdown && (
          <div className="absolute mt-2 w-full bg-white rounded-xl shadow-lg border border-slate-100 overflow-hidden z-50">
            {isSearching ? (
              <div className="flex items-center justify-center p-4 text-slate-500">
                <Loader2 size={20} className="animate-spin mr-2" />
                <span className="text-sm">Đang tìm kiếm...</span>
              </div>
            ) : searchResults.length > 0 ? (
              <ul className="py-2">
                {searchResults.map((result) => (
                  <li key={result.id} className="px-4 py-2 hover:bg-slate-50 cursor-pointer flex flex-col">
                    <span className="text-sm font-medium text-slate-900">{result.title}</span>
                    <span className="text-xs text-slate-500 uppercase mt-0.5">{result.type}</span>
                  </li>
                ))}
              </ul>
            ) : (
              <div className="p-4 text-center text-sm text-slate-500">
                Không tìm thấy kết quả nào
              </div>
            )}
          </div>
        )}
      </div>

      {/* Right side: Notifications & Avatar */}
      <div className="w-1/4 flex items-center justify-end gap-4">
        <button className="relative p-2 rounded-full text-slate-400 hover:bg-slate-100 hover:text-slate-600 transition-colors">
          <Bell size={20} />
          <span className="absolute top-1.5 right-1.5 block w-2 h-2 rounded-full bg-rose-500 ring-2 ring-white"></span>
        </button>
        
        <div className="h-8 w-8 rounded-full bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center text-white font-medium shadow-md cursor-pointer hover:opacity-90 transition-opacity">
          <User size={16} />
        </div>
      </div>
    </header>
  );
}
